<?php
require_once 'functions.php'; require_admin();
if (isset($_GET['download']) && $_GET['download'] === 'csv') {
    log_action($pdo,'Exported CSV report','Reports','Disciplinary cases CSV');
    $pdo->prepare("INSERT INTO reports (generated_by, report_type) VALUES (?, 'Disciplinary cases CSV')")->execute([current_user()['user_id']]);
    $rows = $pdo->query("SELECT s.student_number, CONCAT(s.first_name,' ',s.last_name) student_name, v.violation_name, c.incident_date, c.sanction, c.status, c.remarks FROM cases c JOIN students s ON s.student_id=c.student_id JOIN violations v ON v.violation_id=c.violation_id ORDER BY c.incident_date DESC")->fetchAll();
    header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="ssdrs_disciplinary_report.csv"');
    $out = fopen('php://output','w'); fputcsv($out,['Student Number','Student Name','Violation','Incident Date','Sanction','Status','Remarks']);
    foreach($rows as $r) fputcsv($out,$r); fclose($out); exit;
}
$reports = $pdo->query('SELECT r.report_id, r.report_type, r.generated_date, u.full_name FROM reports r JOIN users u ON u.user_id=r.generated_by ORDER BY r.generated_date DESC LIMIT 20')->fetchAll();
page_header('Reports');
?>
<h1>Reports</h1><p class="muted">Export disciplinary cases for review. Handle exported files confidentially.</p>
<section class="panel"><h2>Disciplinary Records Report</h2><p>Exports student number, student name, violation, date, sanction, status, and remarks.</p><a class="btn primary" href="report.php?download=csv">Download CSV Report</a></section>
<section class="panel"><h2>Recent Report History</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Report Type</th><th>Generated By</th><th>Date</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><?=e($r['report_id'])?></td><td><?=e($r['report_type'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['generated_date'])?></td></tr><?php endforeach; ?><?php if(!$reports): ?><tr><td colspan="4">No reports generated yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php page_footer(); ?>
